27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
49	        message = "Phone number must be in E.164 form: a leading '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "household_member_count")
74	    private Integer householdMemberCount;
75	
76	    @Column(name = "membership_number")
77	    private String membershipNumber;
78	
79	    @Column(name = "membership_level")
80	    private Integer membershipLevel;
81	
82	    @Column(name = "bulk_signup_warning")
83	    private Boolean bulkSignupWarning;
84	
85	    @Column(name = "possible_duplicate")
86	    private Boolean possibleDuplicate;
87	
88	    @Column(name = "possible_duplicate_of")
89	    private Integer possibleDuplicateOf;
90	
91	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
92	    private Set<Pet> pets;
93	
94	    public String getAddress() {
95	        return this.address;
96	    }
97	
98	    public void setAddress(String address) {
99	        this.address = address;
100	    }
101	
102	    public String getCity() {
103	        return this.city;
104	    }
105	
106	    public void setCity(String city) {
107	        this.city = city;
108	    }
109	
110	    public String getTelephone() {
111	        return this.telephone;
112	    }
113	
114	    public void setTelephone(String telephone) {
115	        this.telephone = telephone;
116	    }
117	
118	    public String getEmail() {
119	        return this.email;
120	    }
121	
122	    public void setEmail(String email) {
123	        this.email = email;
124	    }
125	
126	    public String getPostcode() {
127	        return this.postcode;
128	    }
129	
130	    public void setPostcode(String postcode) {
131	        this.postcode = postcode;
132	    }
133	
134	    public LocalDate getRegistrationDate() {
135	        return this.registrationDate;
136	    }
137	
138	    public void setRegistrationDate(LocalDate registrationDate) {
139	        this.registrationDate = registrationDate;
140	    }
141	
142	    public LocalDate getBirthDate() {
143	        return this.birthDate;
144	    }
145	
146	    public void setBirthDate(LocalDate birthDate) {
147	        this.birthDate = birthDate;
148	    }
149	
150	    public String getCustomerCode() {
151	        return this.customerCode;
152	    }
153	
154	    public void setCustomerCode(String customerCode) {
155	        this.customerCode = customerCode;
156	    }
157	
158	    public String getHouseholdId() {
159	        return this.householdId;
160	    }
161	
162	    public void setHouseholdId(String householdId) {
163	        this.householdId = householdId;
164	    }
165	
166	    public Integer getNamesakeCount() {
167	        return this.namesakeCount;
168	    }
169	
170	    public void setNamesakeCount(Integer namesakeCount) {
171	        this.namesakeCount = namesakeCount;
172	    }
173	
174	    public Integer getHouseholdMemberCount() {
175	        return this.householdMemberCount;
176	    }
177	
178	    public void setHouseholdMemberCount(Integer householdMemberCount) {
179	        this.householdMemberCount = householdMemberCount;
180	    }
181	
182	    public String getMembershipNumber() {
183	        return this.membershipNumber;
184	    }
185	
186	    public void setMembershipNumber(String membershipNumber) {
187	        this.membershipNumber = membershipNumber;
188	    }
189	
190	    public Integer getMembershipLevel() {
191	        return this.membershipLevel;
192	    }
193	
194	    public void setMembershipLevel(Integer membershipLevel) {
195	        this.membershipLevel = membershipLevel;
196	    }
197	
198	    public Boolean getBulkSignupWarning() {
199	        return this.bulkSignupWarning;
200	    }
201	
202	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
203	        this.bulkSignupWarning = bulkSignupWarning;
204	    }
205	
206	    public Boolean getPossibleDuplicate() {
207	        return this.possibleDuplicate;
208	    }
209	
210	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
211	        this.possibleDuplicate = possibleDuplicate;
212	    }
213	
214	    public Integer getPossibleDuplicateOf() {
215	        return this.possibleDuplicateOf;
216	    }
217	
218	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
219	        this.possibleDuplicateOf = possibleDuplicateOf;
220	    }
221	
222	    protected Set<Pet> getPetsInternal() {
223	        if (this.pets == null) {
224	            this.pets = new HashSet<>();
225	        }
226	        return this.pets;
227	    }
228	
229	    protected void setPetsInternal(Set<Pet> pets) {
230	        this.pets = pets;
231	    }
232	
233	    public List<Pet> getPets() {
234	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
235	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
236	        return Collections.unmodifiableList(sortedPets);
237	    }
238	
239	    public void setPets(List<Pet> pets) {
240	        this.pets = new HashSet<>(pets);
241	    }
242	
243	    public void addPet(Pet pet) {
244	        getPetsInternal().add(pet);
245	        pet.setOwner(this);
246	    }
247	
248	    /**
249	     * Return the Pet with the given name, or null if none found for this Owner.
250	     *
251	     * @param name to test
252	     * @return true if pet name is already in use
253	     */
254	    public Pet getPet(String name) {
255	        return getPet(name, false);
256	    }
257	
258	    /**
259	     * Return the Pet with the given name, or null if none found for this Owner.
260	     *
261	     * @param name to test
262	     * @return true if pet name is already in use
263	     */
264	    public Pet getPet(String name, boolean ignoreNew) {
265	        name = name.toLowerCase();
266	        for (Pet pet : getPetsInternal()) {
267	            if (!ignoreNew || !pet.isNew()) {
268	                String compName = pet.getName();
269	                compName = compName.toLowerCase();
270	                if (compName.equals(name)) {
271	                    return pet;
272	                }
273	            }
274	        }
275	        return null;
276	    }
277	
278	    public Pet getPet(Integer petId) {
279	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
280	    }
281	
282	    @Override
283	    public String toString() {
284	        return new ToStringCreator(this)
285	
286	            .append("id", this.getId())
287	            .append("new", this.isNew())
288	            .append("lastName", this.getLastName())
289	            .append("firstName", this.getFirstName())
290	            .append("address", this.address)
291	            .append("city", this.city)
292	            .append("telephone", this.telephone)
293	            .append("email", this.email)
294	            .toString();
295	    }
296	}
