68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Dedicated audit logger. On a successful create an audit line carrying the new owner's id,
75	     * {@code customerCode}, {@code registrationDate} and {@code membershipLevel} is emitted to the
76	     * logger named {@code AUDIT}.
77	     */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    /**
81	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
82	     * at least one dot and no whitespace on either side.
83	     */
84	    private static final Pattern EMAIL_PATTERN =
85	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
86	
87	    /**
88	     * Disposable email domains that an owner's email may not use. An email whose domain (the part
89	     * after the {@code @}, compared case-insensitively) is on this list is rejected with a 400
90	     * response naming {@code email}.
91	     */
92	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
93	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
94	
95	    /**
96	     * Common street-type abbreviations expanded during address normalization. Keys are the
97	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
98	     * expanded form.
99	     */
100	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
101	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
102	
103	    /**
104	     * Required national-number length per E.164 country code (the digits that follow the country
105	     * code). {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
106	     * A country code that is not listed here is not length-checked, keeping other numbers accepted.
107	     */
108	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH =
109	        Map.of("1", 10, "61", 9);
110	
111	    /**
112	     * Inclusive 4-digit postcode range allowed for each known region, keyed by the region an owner's
113	     * city derives to (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD): NSW 2000-2099, VIC
114	     * 3000-3099, QLD 4000-4099. A city that derives to no known region ({@code "UNKNOWN"}) is not in
115	     * this table and accepts any 4-digit postcode.
116	     */
117	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
118	        "NSW", new int[] {2000, 2099},
119	        "VIC", new int[] {3000, 3099},
120	        "QLD", new int[] {4000, 4099});
121	
122	    /**
123	     * The maximum number of owners a single city may contain. A create request for a city that
124	     * already holds this many owners is rejected with a 409 response.
125	     */
126	    private static final int MAX_OWNERS_PER_CITY = 50;
127	
128	    /**
129	     * The maximum number of owners that may be registered in a single day. A create request made
130	     * once this many owners already carry today's {@code registrationDate} is rejected with a 429
131	     * response.
132	     */
133	    private static final int MAX_OWNERS_PER_DAY = 100;
134	
135	    /**
136	     * The number of owners that must already carry a day's {@code registrationDate} before a create
137	     * for that day is flagged as a bulk signup. Once more than this many owners already exist for the
138	     * day, the new owner is created with {@code bulkSignupWarning} set to {@code true}.
139	     */
140	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
141	
142	    /**
143	     * The tenure, in days, an owner must exceed to reach {@code membershipLevel} 4. Tenure accrues
144	     * from membership, so a newly created owner (zero tenure) never clears this threshold and is
145	     * therefore capped at level 3 on create.
146	     */
147	    private static final int TENURE_LEVEL_THRESHOLD_DAYS = 365;
148	
149	    private final ClinicService clinicService;
150	
151	    private final OwnerMapper ownerMapper;
152	
153	    private final PetMapper petMapper;
154	
155	    private final VisitMapper visitMapper;
156	
157	    public OwnerRestControllerV1(ClinicService clinicService,
158	                                 OwnerMapper ownerMapper,
159	                                 PetMapper petMapper,
160	                                 VisitMapper visitMapper) {
161	        this.clinicService = clinicService;
162	        this.ownerMapper = ownerMapper;
163	        this.petMapper = petMapper;
164	        this.visitMapper = visitMapper;
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
170	        Collection<Owner> owners;
171	        if (lastName != null) {
172	            owners = this.clinicService.findOwnerByLastName(lastName);
173	        } else {
174	            owners = this.clinicService.findAllOwners();
175	        }
176	        if (owners.isEmpty()) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
185	        Owner owner = this.clinicService.findOwnerById(ownerId);
186	        if (owner == null) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
195	        normalizeAddress(ownerFieldsDto);
196	        validateRequiredFields(ownerFieldsDto);
197	        normalizeTelephone(ownerFieldsDto);
198	        normalizeEmail(ownerFieldsDto);
199	        validatePostcode(ownerFieldsDto);
200	        String householdId = computeHouseholdId(ownerFieldsDto);
201	        rejectDuplicate(ownerFieldsDto, householdId);
202	        rejectCityAtCapacity(ownerFieldsDto);
203	        resolveRegistrationDate(ownerFieldsDto);
204	        rejectDailyLimitReached(ownerFieldsDto.getRegistrationDate());
205	        HttpHeaders headers = new HttpHeaders();
206	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
207	        owner.setHouseholdId(householdId);
208	        assignCustomerCode(owner);
209	        assignMembershipNumber(owner);
210	        assignNamesakeCount(owner);
211	        assignMembershipLevel(owner);
212	        assignBulkSignupWarning(owner);
213	        assignPossibleDuplicate(owner, ownerFieldsDto);
214	        assignHouseholdMembership(owner);
215	        this.clinicService.saveOwner(owner);
216	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
217	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
218	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
219	        headers.setLocation(UriComponentsBuilder.newInstance()
220	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
221	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
227	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
228	        if (currentOwner == null) {
229	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	        }
231	        currentOwner.setAddress(ownerFieldsDto.getAddress());
232	        currentOwner.setCity(ownerFieldsDto.getCity());
233	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
234	        currentOwner.setLastName(ownerFieldsDto.getLastName());
235	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
236	        normalizeEmail(ownerFieldsDto);
237	        currentOwner.setEmail(ownerFieldsDto.getEmail());
238	        this.clinicService.saveOwner(currentOwner);
239	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Transactional
244	    @Override
245	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner == null) {
248	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	        }
250	        this.clinicService.deleteOwner(owner);
251	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner == null) {
259	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	        }
261	        HttpHeaders headers = new HttpHeaders();
262	        Pet pet = petMapper.toPet(petFieldsDto);
263	        owner.setId(ownerId);
264	        pet.setOwner(owner);
265	        pet.getType().setName(null);
266	        this.clinicService.savePet(pet);
267	        PetDto petDto = petMapper.toPetDto(pet);
268	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
269	            .buildAndExpand(pet.getId()).toUri());
270	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
271	    }
272	
273	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
274	    @Override
275	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
276	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
277	        if (currentOwner != null) {
278	            Pet currentPet = this.clinicService.findPetById(petId);
279	            if (currentPet != null) {
280	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
281	                currentPet.setName(petFieldsDto.getName());
282	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
283	                this.clinicService.savePet(currentPet);
284	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
285	            }
286	        }
287	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
288	    }
289	
290	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
291	    @Override
292	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
293	        HttpHeaders headers = new HttpHeaders();
294	        Visit visit = visitMapper.toVisit(visitFieldsDto);
295	        Pet pet = new Pet();
296	        pet.setId(petId);
297	        visit.setPet(pet);
298	        this.clinicService.saveVisit(visit);
299	        VisitDto visitDto = visitMapper.toVisitDto(visit);
300	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
301	            .buildAndExpand(visit.getId()).toUri());
302	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
303	    }
304	
305	
306	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
307	    @Override
308	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
309	        Owner owner = this.clinicService.findOwnerById(ownerId);
310	        if (owner != null) {
311	            Pet pet = owner.getPet(petId);
312	            if (pet != null) {
313	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
314	            }
315	        }
316	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
317	    }
318	
319	    /**
320	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
321	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
322	     * does not catch). The names of all offending fields are collected so the caller receives a
323	     * 400 response whose {@code errors} array lists each one.
324	     */
325	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
326	        List<String> missingFields = new ArrayList<>();
327	        if (isBlank(ownerFieldsDto.getFirstName())) {
328	            missingFields.add("firstName");
329	        }
330	        if (isBlank(ownerFieldsDto.getLastName())) {
331	            missingFields.add("lastName");
332	        }
333	        if (isBlank(ownerFieldsDto.getAddress())) {
334	            missingFields.add("address");
335	        }
336	        if (isBlank(ownerFieldsDto.getCity())) {
337	            missingFields.add("city");
338	        }
339	        if (isBlank(ownerFieldsDto.getTelephone())) {
340	            missingFields.add("telephone");
341	        }
342	        if (!missingFields.isEmpty()) {
343	            throw new InvalidOwnerFieldsException(missingFields);
344	        }
345	    }
