351	    /**
352	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
353	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
354	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
355	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
356	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
357	     * means an address that is blank after normalization is rejected like a missing one.
358	     */
359	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
360	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
361	    }
