363	    /**
364	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
365	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
366	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
367	     * address is returned unchanged, making it safe to apply to stored values during comparison.
368	     */
369	    private static String canonicalAddress(String address) {
370	        if (address == null) {
371	            return null;
372	        }
373	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
374	        if (collapsed.isEmpty()) {
375	            return "";
376	        }
377	        String[] tokens = collapsed.split(" ");
378	        StringBuilder sb = new StringBuilder(collapsed.length());
379	        for (int i = 0; i < tokens.length; i++) {
380	            if (i > 0) {
381	                sb.append(' ');
382	            }
383	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
384	        }
385	        return sb.toString();
386	    }
