403	    /**
404	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
405	     * (400) naming {@code telephone} when it cannot form a valid number.
406	     */
407	    private static String toE164(String telephone) {
408	        if (telephone == null) {
409	            throw new InvalidOwnerFieldsException(List.of("telephone"));
410	        }
411	        boolean hasCountryCode = telephone.trim().startsWith("+");
412	        String digits = telephone.replaceAll("\\D", "");
413	        String countryCode;
414	        String national;
415	        if (hasCountryCode) {
416	            countryCode = matchCountryCode(digits);
417	            national = digits;
418	        } else {
419	            countryCode = "61";
420	            if (digits.startsWith("0")) {
421	                digits = digits.substring(1);
422	            }
423	            national = "61" + digits;
424	        }
425	        if (!national.matches("[0-9]{8,15}")) {
426	            throw new InvalidOwnerFieldsException(List.of("telephone"));
427	        }
428	        if (countryCode != null) {
429	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
430	            if (requiredLength != null
431	                && national.length() - countryCode.length() != requiredLength) {
432	                throw new InvalidOwnerFieldsException(List.of("telephone"));
433	            }
434	        }
435	        return "+" + national;
436	    }
437	
438	    /**
439	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
440	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
441	     * the number is not length-checked against a country.
442	     */
443	    private static String matchCountryCode(String digits) {
444	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
445	            .filter(digits::startsWith)
446	            .max(Comparator.comparingInt(String::length))
447	            .orElse(null);
448	    }
