450	    /**
451	     * Rejects creating an owner that duplicates an existing one, either as a household duplicate or
452	     * as an exact identity duplicate. The household is now keyed on the computed {@code householdId}
453	     * (a deterministic function of the normalized last name and postcode, see
454	     * {@link #computeHouseholdId}), so any existing owner already carrying the same {@code householdId}
455	     * belongs to the same household and makes the new owner a household duplicate. Independently, an
456	     * exact match on the derived {@code identityKey} - {@code normalizedTelephone + '|' + (email or
457	     * empty) + '|' + (householdId or empty)} - is also a duplicate; this still catches owners with no
458	     * postcode (and therefore no household) that share a telephone and email. Both checks are a 409.
459	     *
460	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block: a request that opts in
461	     * is allowed through even when it lands in an existing household, so it is created as a declared
462	     * household member rather than rejected. The incoming telephone and email have already been
463	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}; each existing owner's key
464	     * is derived the same way before comparison. A match results in a 409 response naming
465	     * {@code identityKey}.
466	     */
467	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId) {
468	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
469	            return;
470	        }
471	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
472	        for (Owner existing : this.clinicService.findAllOwners()) {
473	            boolean householdDuplicate = householdId != null && householdId.equals(existing.getHouseholdId());
474	            if (householdDuplicate || identityKey.equals(existingIdentityKey(existing))) {
475	                throw new DuplicateOwnerIdentityException(identityKey);
476	            }
477	        }
478	    }
