480	    /**
481	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
482	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
483	     * are expected to already be in their normalized (E.164, lower-cased) forms.
484	     */
485	    private static String identityKey(String telephone, String email, String householdId) {
486	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
487	    }
488	
489	    /**
490	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
491	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
492	     * the stored email is lower-cased, and the stored household id is used as-is.
493	     */
494	    private static String existingIdentityKey(Owner existing) {
495	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
496	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
497	        return identityKey(telephone, email, existing.getHouseholdId());
498	    }
499	
500	    private static String orEmpty(String value) {
501	        return value == null ? "" : value;
502	    }
