504	    /**
505	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
506	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
507	     */
508	    private static String normalizeExisting(String telephone) {
509	        try {
510	            return toE164(telephone);
511	        } catch (InvalidOwnerFieldsException ex) {
512	            return null;
513	        }
514	    }
