516	    /**
517	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
518	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
519	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
520	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
521	     */
522	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
523	        String city = ownerFieldsDto.getCity();
524	        int count = 0;
525	        for (Owner existing : this.clinicService.findAllOwners()) {
526	            if (city.equalsIgnoreCase(existing.getCity())) {
527	                count++;
528	            }
529	        }
530	        if (count >= MAX_OWNERS_PER_CITY) {
531	            throw new OwnerCityAtCapacityException(city);
532	        }
533	    }
