535	    /**
536	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
537	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
538	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
539	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
540	     */
541	    private void rejectDailyLimitReached(LocalDate registrationDate) {
542	        int count = 0;
543	        for (Owner existing : this.clinicService.findAllOwners()) {
544	            if (registrationDate.equals(existing.getRegistrationDate())) {
545	                count++;
546	            }
547	        }
548	        if (count >= MAX_OWNERS_PER_DAY) {
549	            throw new DailyOwnerLimitReachedException(registrationDate);
