553	    /**
554	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
555	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
556	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
557	     */
558	    private static String normalizeForComparison(String value) {
559	        if (value == null) {
560	            return "";
561	        }
562	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
563	    }
