588	    /**
589	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
590	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
591	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
592	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
593	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
594	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
595	     * as-is so it is stored and returned.
596	     */
597	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
598	        String postcode = ownerFieldsDto.getPostcode();
599	        if (postcode == null) {
600	            return;
601	        }
602	        if (!postcode.matches("[0-9]{4}")) {
603	            throw new InvalidOwnerFieldsException(List.of("postcode"));
604	        }
605	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
606	        if (range != null) {
607	            int value = Integer.parseInt(postcode);
608	            if (value < range[0] || value > range[1]) {
609	                throw new InvalidOwnerFieldsException(List.of("postcode"));
610	            }
611	        }
612	    }
