635	    /**
636	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
637	     * Monday; a weekday is returned unchanged.
638	     */
639	    private static LocalDate toBusinessDay(LocalDate date) {
640	        return switch (date.getDayOfWeek()) {
641	            case SATURDAY -> date.plusDays(2);
642	            case SUNDAY -> date.plusDays(1);
643	            default -> date;
644	        };
645	    }
