662	    /**
663	     * Assigns the owner's {@code membershipNumber} on create, formatted
664	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
665	     * {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Assigned after
666	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
667	     * inputs are present.
668	     */
