674	    /**
675	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
676	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
677	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
678	     */
679	    private void assignNamesakeCount(Owner owner) {
680	        String firstName = owner.getFirstName();
681	        String lastName = owner.getLastName();
682	        int count = 0;
683	        for (Owner existing : this.clinicService.findAllOwners()) {
684	            if (firstName.equalsIgnoreCase(existing.getFirstName())
685	                && lastName.equalsIgnoreCase(existing.getLastName())) {
686	                count++;
687	            }
688	        }
689	        owner.setNamesakeCount(count);
690	    }
