692	    /**
693	     * Assigns the new owner's {@code membershipLevel} on create: a number from 1 to 3 starting at
694	     * 1, plus 1 when an email is present, plus 1 when {@code namesakeCount} is 0, capped at 3.
695	     * Level 4 is reserved for owners whose tenure exceeds {@value #TENURE_LEVEL_THRESHOLD_DAYS}
696	     * days; a newly created owner has zero tenure, so on create the level never exceeds 3. Runs
697	     * after {@link #assignNamesakeCount} so that count is settled.
698	     */
699	    private void assignMembershipLevel(Owner owner) {
700	        int level = 1;
701	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
702	            level++;
703	        }
704	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
705	            level++;
706	        }
707	        level = Math.min(level, 3);
708	        if (tenureDays(owner) > TENURE_LEVEL_THRESHOLD_DAYS) {
709	            level = 4;
710	        }
711	        owner.setMembershipLevel(level);
712	    }
