741	    /**
742	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
743	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
744	     * possible duplicate when an existing owner shares its {@code lastName} (compared
745	     * case-insensitively) and its {@code postcode} (a present, exact match) while carrying a different
746	     * {@code telephone}. When such an owner exists, {@code possibleDuplicate} is set to {@code true}
747	     * and {@code possibleDuplicateOf} to that owner's id (the lowest id when several match); otherwise
748	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is left {@code null}.
749	     * Computed before the new owner is persisted, so it considers only the pre-existing owners.
750	     *
751	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
752	     * has deliberately opted into an existing household, so its shared last name and postcode are
753	     * expected rather than a suspected duplicate.
754	     */
755	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
756	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
757	            owner.setPossibleDuplicate(false);
758	            owner.setPossibleDuplicateOf(null);
759	            return;
760	        }
761	        String lastName = owner.getLastName();
762	        String postcode = owner.getPostcode();
763	        String telephone = owner.getTelephone();
764	        Integer matchId = null;
765	        if (postcode != null) {
766	            for (Owner existing : this.clinicService.findAllOwners()) {
767	                if (lastName.equalsIgnoreCase(existing.getLastName())
768	                    && postcode.equals(existing.getPostcode())
769	                    && !postcode.isBlank()
770	                    && !java.util.Objects.equals(telephone, existing.getTelephone())
771	                    && existing.getId() != null
772	                    && (matchId == null || existing.getId() < matchId)) {
773	                    matchId = existing.getId();
774	                }
775	            }
776	        }
777	        owner.setPossibleDuplicate(matchId != null);
778	        owner.setPossibleDuplicateOf(matchId);
779	    }
