781	    /**
782	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
783	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
784	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
785	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
786	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
787	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
788	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
789	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
790	     * ({@link #assignHouseholdMembership}).
791	     */
792	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
793	        String postcode = ownerFieldsDto.getPostcode();
794	        if (postcode == null || postcode.isBlank()) {
795	            return null;
796	        }
797	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
798	        return shaHexUpper(lastName + "|" + postcode, 12);
799	    }
