801	    /**
802	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
803	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
804	     * every existing owner already carrying the same identifier. Runs after the owner's
805	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
806	     * Left {@code null} when the owner belongs to no household.
807	     */
808	    private void assignHouseholdMembership(Owner owner) {
809	        String householdId = owner.getHouseholdId();
810	        if (householdId == null || householdId.isBlank()) {
811	            owner.setHouseholdMemberCount(null);
812	            return;
813	        }
814	        int count = 1;
815	        for (Owner existing : this.clinicService.findAllOwners()) {
816	            if (householdId.equals(existing.getHouseholdId())) {
817	                count++;
818	            }
819	        }
820	        owner.setHouseholdMemberCount(count);
821	    }
