823	    /**
824	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
825	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
826	     * identifier, both stable functions of their inputs.
827	     */
828	    private static String shaHexUpper(String input, int length) {
829	        try {
830	            byte[] digest = MessageDigest.getInstance("SHA-256")
831	                .digest(input.getBytes(StandardCharsets.UTF_8));
832	            StringBuilder hex = new StringBuilder(digest.length * 2);
833	            for (byte b : digest) {
834	                hex.append(String.format("%02x", b));
835	            }
836	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
837	        } catch (NoSuchAlgorithmException ex) {
838	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
839	        }
840	    }
